(7318983, 1141707, 69324, '<td valign="top">Would of been my top pick, nicely done.</td>', 'Would of been my top pick, nicely done.', '2015-02-20 17:39:49.000000', NULL, 0),
(7319062, 1141777, 5822, '<td valign="top">I really like the way you''ve carried out this concept of time traveler. It''s as if she''s just appeared from another time/dimension, middle ages costume, into our modern industrial times - the bottle top and can/bottle opener sculpture. The ghostly figures and flow  of their line of movement are wonderful. I think this meets the challenge well.</td>', 'I really like the way you''ve carried out this concept of time traveler. It''s as if she''s just appeared from another time/dimension, middle ages costume, into our modern industrial times - the bottle top and can/bottle opener sculpture. The ghostly figures and flow  of their line of movement are wonderful. I think this meets the challenge well.', '2015-02-20 21:48:05.000000', NULL, 0),
(7319162, 1141589, 70265, '<td valign="top">This is soooo good! Would love to know your processing details.</td>', 'This is soooo good! Would love to know your processing details.', '2015-02-21 08:58:25.000000', NULL, 0),
(7319182, 1141589, 100831, '<td valign="top">Well done, Lydia! Congrats!</td>', 'Well done, Lydia! Congrats!', '2015-02-21 11:18:35.000000', NULL, 0),
(7319291, 1141811, 52549, '<td valign="top">Congrats on the ribbon, Judi.</td>', 'Congrats on the ribbon, Judi.', '2015-02-21 14:14:27.000000', NULL, 0),
(7319296, 1141589, 52549, '<td valign="top">Not quite my top three hope for you, but still pretty darn good. Congrats on the HM, my friend.</td>', 'Not quite my top three hope for you, but still pretty darn good. Congrats on the HM, my friend.', '2015-02-21 14:15:44.000000', NULL, 0),
(7319398, 1141707, 50695, '<td valign="top">well done</td>', 'well done', '2015-02-21 16:28:15.000000', NULL, 0),
