(7319403, 1141467, 50695, '<td valign="top">Master Perigrene Accordion-neck</td>', 'Master Perigrene Accordion-neck', '2015-02-21 16:33:53.000000', NULL, 0),
(7319405, 1141803, 50695, '<td valign="top">nice blurscape</td>', 'nice blurscape', '2015-02-21 16:34:27.000000', NULL, 0),
(7319406, 1141820, 50695, '<td valign="top">I would say claw marks</td>', 'I would say claw marks', '2015-02-21 16:34:50.000000', NULL, 0),
(7319561, 1141811, 114969, '<td valign="top">So impressive! I love all the details everywhere, and the outfit is pure awesomeness. The border is great as well. Great work, congratulations on your ribbon.</td>', 'So impressive! I love all the details everywhere, and the outfit is pure awesomeness. The border is great as well. Great work, congratulations on your ribbon.', '2015-02-21 19:45:45.000000', NULL, 0),
(7319599, 1141828, 114969, '<td valign="top">Gorgeous outfits and models! I also love the creativity with the concept, very nice idea. Congrats on the ribbon!</td>', 'Gorgeous outfits and models! I also love the creativity with the concept, very nice idea. Congrats on the ribbon!', '2015-02-21 20:02:59.000000', NULL, 0),
(7319606, 1141724, 114969, '<td valign="top">Wow, so much work, very impressive! The result looks fantastic, I''m sure your daughter is going to enjoy the print a lot. Congratulations on the great finish too, even though it really deserved a ribbon imho.</td>', 'Wow, so much work, very impressive! The result looks fantastic, I''m sure your daughter is going to enjoy the print a lot. Congratulations on the great finish too, even though it really deserved a ribbon imho.', '2015-02-21 20:05:05.000000', NULL, 0),
(7319921, 1141724, 43463, '<td valign="top">Pam, love this fantastic creation! Your model (your lovely daughter) is fantastic as Professor Buckly - more power to ladies in science and in science fiction!!! I love your metal menagerie you created as well...the owl is my favorite. Congrats on the 4th place finish</td>', 'Pam, love this fantastic creation! Your model (your lovely daughter) is fantastic as Professor Buckly - more power to ladies in science and in science fiction!!! I love your metal menagerie you created as well...the owl is my favorite. Congrats on the 4th place finish', '2015-02-22 10:04:49.000000', NULL, 0),
(7319994, 1141707, 116247, '<td valign="top">Great entry Mary Ann! Congrats on the top 10!</td>', 'Great entry Mary Ann! Congrats on the top 10!', '2015-02-22 13:42:10.000000', NULL, 0),
(7320319, 1141589, 114969, '<td valign="top">Beautiful work. The model is gorgeous, and the choice of delicate pastel tones suits the scene perfectly. Regarding the editing steps, in fact, I almost always start with a relatively bright scene: it is easier to darken parts (essentially to grab the viewer''s attention to the remaining brighter areas) than to bring out details from an already dark photo. Of course it is not a rule, and great results can be obtained other ways, as you demonstrated here. Congrats on the top 5!</td>', 'Beautiful work. The model is gorgeous, and the choice of delicate pastel tones suits the scene perfectly. Regarding the editing steps, in fact, I almost always start with a relatively bright scene: it is easier to darken parts (essentially to grab the viewer''s attention to the remaining brighter areas) than to bring out details from an already dark photo. Of course it is not a rule, and great results can be obtained other ways, as you demonstrated here. Congrats on the top 5!', '2015-02-23 08:45:42.000000', NULL, 0),
(7320415, 1141832, 46177, '<td valign="top">Congratulations on your well deserved blue ribbon.</td>', 'Congratulations on your well deserved blue ribbon.', '2015-02-23 12:06:09.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7320416, 1141811, 46177, '<td valign="top">Love the outfit, great shot. Congratulations on your red.</td>', 'Love the outfit, great shot. Congratulations on your red.', '2015-02-23 12:06:51.000000', NULL, 0),
(7320417, 1141828, 46177, '<td valign="top">Very cool shot, congratulations on your yellow ribbon.</td>', 'Very cool shot, congratulations on your yellow ribbon.', '2015-02-23 12:07:36.000000', NULL, 0),
(7320418, 1141724, 46177, '<td valign="top">Your daughter is beautiful, amazing eyes! Congratulations on your HM.</td>', 'Your daughter is beautiful, amazing eyes! Congratulations on your HM.', '2015-02-23 12:08:28.000000', NULL, 0),
(7320419, 1141589, 46177, '<td valign="top">Love the colours and pose, well done. Congratulations on your HM.</td>', 'Love the colours and pose, well done. Congratulations on your HM.', '2015-02-23 12:10:35.000000', NULL, 0),
(7320420, 1141835, 46177, '<td valign="top">So imaginative, congratulations on your top 10 image.</td>', 'So imaginative, congratulations on your top 10 image.', '2015-02-23 12:11:20.000000', NULL, 0),
(7320421, 1141831, 46177, '<td valign="top">Congratulations on your top 10 image, love the pipe and hat!</td>', 'Congratulations on your top 10 image, love the pipe and hat!', '2015-02-23 12:12:26.000000', NULL, 0),
(7320422, 1141843, 46177, '<td valign="top">Love all the things you put in this image, the train balloons, so much fun. Congratulations on your top 10 image.</td>', 'Love all the things you put in this image, the train balloons, so much fun. Congratulations on your top 10 image.', '2015-02-23 12:13:33.000000', NULL, 0),
(7320425, 1141707, 46177, '<td valign="top">Congratulations on your top 10 image, very cool shot.</td>', 'Congratulations on your top 10 image, very cool shot.', '2015-02-23 12:14:21.000000', NULL, 0),
(7320426, 1141774, 46177, '<td valign="top">Great outfits and cute models, congratulations on your top 10 image.</td>', 'Great outfits and cute models, congratulations on your top 10 image.', '2015-02-23 12:15:18.000000', NULL, 0),
(7320536, 1141808, 150277, '<td valign="top">Beautiful image.  I was shocked when I saw the 5 average, although apparently some folks thought it was a DNMC for steampunk?  Well, I still like it and thought it was very creative.</td>', 'Beautiful image.  I was shocked when I saw the 5 average, although apparently some folks thought it was a DNMC for steampunk?  Well, I still like it and thought it was very creative.', '2015-02-23 17:16:53.000000', NULL, 0),
(7321283, 1141852, 112828, '<td valign="top">Great pen</td>', 'Great pen', '2015-02-26 17:17:48.000000', NULL, 0),
(7396265, 1141843, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>Congratulations for your top ten placing for a fun image that meets the challenge well.<br/> <br/>There must have been a lot of time and effort that went into the creation of this appealing and humorous image. I am not at all qualified to critique your compositing skills, although I have a basic appreciation I have never done any at all so I will approach this from the end result as an image in its own right regardless of the process involved.<br/> <br/>My first impressions are of a fun image that has been well executed for an impressive end result. I like your composition with the main character in the lower right with plenty of fascinating detail throughout the rest of the image. I love his ''Heath Robinson'' gun so intricately constructed and implausible that one would imagine on pulling the trigger a flag appearing with the word ''bang!''. The facial additions and his expression make him look deadly in an ''only joking'' sort of way that adds to the humorous impression.<br/> <br/>The background landscape is all very interesting and convincingly conceived, I like the steam train and its position but most of all I adore that airship its really the icing on the cake adding the final confirmation that this is an image to be savoured for its humour.<br/> <br/>Well worth all the effort it must have taken and a pleasure to be able offer my thoughts, such as they are, thank you for submitting, Sid.</td>', '*Hello from Sid and the Critique Club* Congratulations for your top ten placing for a fun image that meets the challenge well. There must have been a lot of time and effort that went into the creation of this appealing and humorous image. I am not at all qualified to critique your compositing skills, although I have a basic appreciation I have never done any at all so I will approach this from the end result as an image in its own right regardless of the process involved. My first impressions are of a fun image that has been well executed for an impressive end result. I like your composition with the main character in the lower right with plenty of fascinating detail throughout the rest of the image. I love his ''Heath Robinson'' gun so intricately constructed and implausible that one would imagine on pulling the trigger a flag appearing with the word ''bang!''. The facial additions and his expression make him look deadly in an ''only joking'' sort of way that adds to the humorous impression. The background landscape is all very interesting and convincingly conceived, I like the steam train and its position but most of all I adore that airship its really the icing on the cake adding the final confirmation that this is an image to be savoured for its humour. Well worth all the effort it must have taken and a pleasure to be able offer my thoughts, such as they are, thank you for submitting, Sid.', '2015-08-10 06:57:28.000000', NULL, 0),
(7458830, 1141835, 97225, '<td valign="top">This is awesome!</td>', 'This is awesome!', '2016-06-06 03:44:35.000000', NULL, 0);
COMMIT;
